{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresi, sistemin çalıştırılması ve sensör girdilerinin verilmesiyle ölçülerek doğrulanabilir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi ile 2.000 iz altında ekran yenileme hızının 10 Hz'in üzerinde kalıp kalmadığı gözlemlenebilir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Operatörün seçtiği izin detaylarını görüntüleyebilmesi, sistemin çalıştırılıp gözlemlenerek gösterilebilir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Zamanlayıcı mantığı, girdi akışının durdurulması ve zamanın izlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye iz girdiğinde görsel ve sesli uyarıların tetiklenip tetiklenmediği çalıştırılarak gözlenebilir."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj iletim gecikmesi ve durum bildirimi, mesaj gönderilerek ve zaman ölçülerek test edilebilir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Kayıt tutma mekanizmasının değiştirilemezliği ve log yapısı, kod veya yapılandırma incelemesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Sunucu arızası senaryosu simüle edilerek devralma süresi ve veri bütünlüğü test edilebilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı girişi yapılarak gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık bekleme süresi sonunda oturumun sonlandırılması ve yönlendirme davranışı, zamanlayıcı testleri ile sistemin çalıştırılması üzerinden doğrulanabilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık süre, senaryo tabanlı testler ile sistemin tepkisi gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti ve adet sınırı kısıtlarının uygulanıp uygulanmadığı, farklı dosyalar yüklenerek sistemin kabul veya reddetme davranışı gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Başvuru tamamlanması sonrası benzersiz numara üretimi ve e-posta gönderimi, uçtan uca test senaryoları ile sistemin çıktısı gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde kaldığı yerden devam etme işlevi, farklı zaman dilimlerinde sisteme erişim sağlanarak gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğu, kullanıcı arayüzü kodunun ve tasarım dokümanlarının erişilebilirlik standartlarına göre gözle denetlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanması, altyapı yapılandırma dosyalarının ve veri merkezi sözleşmelerinin gözle denetlenerek doğrulanabilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda HTTP 429 yanıtı ve Retry-After başlığının, kontrollü istek yükü uygulanarak sistemin davranışının gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Belirli bir yük altında 99. yüzdelik gecikme metriğinin karşılanıp karşılanmadığının belirlenmesi, performans testleri ve istatistiksel analiz gerektirdiği için analiz yöntemi uygundur."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Arka uç zaman aşımı durumunda isteğin sonlandırılması ve HTTP 504 yanıtının, arka uç servisin gecikmeli yanıt vermesi simüle edilerek sistemin davranışının gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yapılandırma değişikliğinin yeniden başlatma olmadan ve aktif istekleri düşürmeden uygulanmasının, sistem çalışırken yapılandırma değişikliği yapılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin yapılandırılmış günlük formatında kaydedilip kaydedilmediğinin ve gerekli alanların (izleme kimliği, süre vb.) içerip içermediğinin, istek gönderilip günlük çıktısının incelenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin hesaplanması, uzun süreli izleme verilerinin istatistiksel analizi gerektirdiği için analiz yöntemi uygundur."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "WCAG 2.1 AA uyumluluğunun davranışsal doğrulanması",
      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Kullanıcı arayüzü yayına alınmış ve test edilebilir durumdadır.",
      "test_inputs": "Ekran okuyucu yazılımı (örn. NVDA, JAWS), klavye, fare.",
      "assumptions": "Sistem, WCAG 2.1 AA kriterlerini (örneğin renk kontrastı, klavye erişimi, alt metin) teknik olarak desteklemektedir.",
      "steps": [
        {
          "no": 1,
          "action": "Klavye yardımıyla (Tab tuşu) arayüzdeki tüm etkileşimli elemanlara sırasıyla erişilir.",
          "expected": "Odak göstergesi her elemanda belirgin şekilde görünür ve sıralama mantıklıdır; hiçbir eleman klavye ile erişilemez durumda değildir."
        },
        {
          "no": 2,
          "action": "Ekran okuyucu yazılımı ile bir form alanı seçilir ve okutulur.",
          "expected": "Alanın etiketi, tipi ve varsa zorunluluk durumu doğru olarak seslendirilir."
        },
        {
          "no": 3,
          "action": "Arayüzdeki görsel içeriklerin (bilgilendirme amaçlı olmayan) alt metinleri (alt text) ekran okuyucu ile kontrol edilir.",
          "expected": "Görsellerin içeriğini açıklayan alt metinler okunabilir ve eksik değildir."
        },
        {
          "no": 4,
          "action": "Sayfa boyutu %200'e büyütülerek (zoom) görüntüleme yapılır.",
          "expected": "İçerik kesilmez, kaydırma çubukları çalışır ve okunabilirlik korunur."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Macro-averaged F1 score verification on held-out set",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The trained classification model is available. A held-out evaluation dataset with ground truth labels is prepared.",
      "test_inputs": "Held-out evaluation dataset containing documents with known correct classifications.",
      "assumptions": "The evaluation script correctly computes the macro-averaged F1 score.",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the held-out evaluation dataset.",
          "expected": "The model produces predicted labels for all documents in the dataset."
        },
        {
          "no": 2,
          "action": "Calculate the macro-averaged F1 score by comparing predicted labels with ground truth labels.",
          "expected": "The calculated macro-averaged F1 score is at least 0.90."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Recall parity between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The trained classification model is available. A held-out evaluation dataset is prepared containing a balanced subset of Turkish and English documents with ground truth labels.",
      "test_inputs": "Held-out evaluation dataset split into two subsets: one containing only Turkish documents and one containing only English documents.",
      "assumptions": "The evaluation script can calculate recall separately for each language subset.",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the subset of Turkish documents in the held-out evaluation set.",
          "expected": "The model produces predicted labels for all Turkish documents."
        },
        {
          "no": 2,
          "action": "Calculate the recall score for the Turkish document subset.",
          "expected": "A specific recall value (R_tr) is obtained for the Turkish documents."
        },
        {
          "no": 3,
          "action": "Run the classification model on the subset of English documents in the held-out evaluation set.",
          "expected": "The model produces predicted labels for all English documents."
        },
        {
          "no": 4,
          "action": "Calculate the recall score for the English document subset.",
          "expected": "A specific recall value (R_en) is obtained for the English documents."
        },
        {
          "no": 5,
          "action": "Calculate the absolute difference between R_tr and R_en in percentage points.",
          "expected": "The absolute difference is less than or equal to 5 percentage points."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-MED-006-01",
      "title": "Verification of AES-256 encryption for stored casualty data",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is powered on and the application is installed. The application has permissions to access the local file system where data is stored.",
      "test_inputs": "A test casualty record containing unique, identifiable data (e.g., Patient ID: \"TEST-123\", Name: \"John Doe\").",
      "assumptions": "The test environment allows direct access to the device's storage files or a tool is available to inspect the file headers/metadata for encryption markers.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record in the application with the test inputs specified.",
          "expected": "The record is successfully saved and appears in the casualty list."
        },
        {
          "no": 2,
          "action": "Close the application and access the underlying storage file or database file where the casualty data is persisted.",
          "expected": "The raw data in the file is not readable as plain text (i.e., it appears as binary or encrypted data)."
        },
        {
          "no": 3,
          "action": "Inspect the file metadata or use a forensic tool to check the encryption algorithm used for the data segment.",
          "expected": "The encryption method is identified as AES-256."
        }
      ]
    },
    {
      "id": "TC-MED-008-01",
      "title": "Battery life verification under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is fully charged (100%). The 'defined usage profile' is documented and includes specific operations (e.g., continuous data entry, screen brightness level, network usage).",
      "test_inputs": "None (automated usage script or manual simulation of the defined profile).",
      "assumptions": "The 'defined usage profile' specifies a consistent set of actions such as: Screen at 50% brightness, GPS active, Wi-Fi active, and continuous data entry every 30 seconds. A timer or battery monitoring tool is available to track remaining charge percentage.",
      "steps": [
        {
          "no": 1,
          "action": "Start the application and begin the defined usage profile simulation (e.g., input data, navigate screens) from a 100% battery state.",
          "expected": "The application runs without crashing, and the battery level starts to decrease."
        },
        {
          "no": 2,
          "action": "Continue the defined usage profile continuously for 8 hours.",
          "expected": "The tablet remains powered on, the application remains responsive, and the battery level does not reach 0% (device does not shut down) within the 8-hour period."
        },
        {
          "no": 3,
          "action": "After 8 hours, check the battery percentage and device status.",
          "expected": "The device is still operating and the battery percentage is greater than 0%."
        }
      ]
    }
  ]
}

