{
  "test_cases": [
    {
      "id": "TC-AI-004-01",
      "title": "95th percentile response time under load",
      "covers": [
        "AI-004"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "The service is deployed and ready to receive traffic. A load generation tool is available.",
      "test_inputs": "50 requests per second for a duration sufficient to reach the 95th percentile (e.g., 1000 requests).",
      "assumptions": "The load generator can measure and report the 95th percentile latency.",
      "steps": [
        {
          "no": 1,
          "action": "Start a load test generating 50 requests per second.",
          "expected": "The service accepts the requests and processes them."
        },
        {
          "no": 2,
          "action": "Wait until at least 1000 requests have been processed to establish a stable percentile.",
          "expected": "The system continues to process requests without crashing or rejecting them due to load."
        },
        {
          "no": 3,
          "action": "Stop the load test and retrieve the 95th percentile response time metric.",
          "expected": "The 95th percentile response time is less than or equal to 500 ms."
        }
      ]
    },
    {
      "id": "TC-AI-005-01",
      "title": "Logging of model version, input hash, and predicted category",
      "covers": [
        "AI-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The service is running and logging is enabled.",
      "test_inputs": "A valid document input for classification.",
      "assumptions": "The logging mechanism stores data in a queryable store (e.g., database or log file).",
      "steps": [
        {
          "no": 1,
          "action": "Send a valid document to the classification service.",
          "expected": "The service returns a successful classification result."
        },
        {
          "no": 2,
          "action": "Query the service logs or database for the record corresponding to this request.",
          "expected": "A record exists containing the model version used, the hash of the input document, and the predicted category."
        },
        {
          "no": 3,
          "action": "Verify the values in the log record against the expected model version and the calculated hash of the input.",
          "expected": "The logged model version matches the active model, the input hash matches the calculated hash, and the category matches the returned result."
        }
      ]
    },
    {
      "id": "TC-AI-006-01",
      "title": "Alert triggered when PSI exceeds 0.2",
      "covers": [
        "AI-006"
      ],
      "type": "Hata",
      "priority": "Yüksek",
